-- Local targeted DDL fixture: exact Staging column definitions captured 2026-09-09.
-- This is not a full V1 schema reproduction; actual Staging qualification tests all live constraints.
create role anon; create role authenticated; create role service_role bypassrls;
create table public.api_keys (
id uuid not null default gen_random_uuid(),
key_name text default 'Private beta key'::text,
key_prefix text,
key_hash text,
owner_email text,
team_id text,
usage_count integer default 0,
revoked boolean default false,
created_at timestamp with time zone default now(),
owner_user_id uuid,
label text,
status text default 'active'::text,
last_used_at timestamp with time zone,
user_id uuid,
user_email text,
rate_limit_status text default 'normal'::text,
tenant_id uuid,
client_id uuid,
scopes text[] not null default '{}'::text[],
expires_at timestamp with time zone,
revoked_at timestamp with time zone,
rotated_from_id uuid,
created_by uuid,
updated_at timestamp with time zone not null default now(),
authority_management_boundary jsonb,
rotation_request_id uuid
);
create table public.canonical_trust_transactions (
transaction_id uuid not null,
enterprise_id uuid not null,
actor_id uuid not null,
actor_type text not null,
subject_type text not null,
subject_id text not null,
workflow_id text not null,
action_type text not null,
action_purpose text not null,
action_resource text not null,
action_environment text not null,
request_digest text not null,
idempotency_key text not null,
correlation_id uuid not null,
requested_at timestamp with time zone not null,
decision text not null,
trust_state text not null,
decision_id uuid not null,
authority_reference text not null,
authority_lineage_references jsonb not null default '[]'::jsonb,
policy_id text not null,
policy_version text not null,
policy_hash text not null,
evidence_references jsonb not null default '[]'::jsonb,
evidence_digest text not null,
evidence_complete boolean not null,
evidence_fresh boolean not null,
reason_codes text[] not null default '{}'::text[],
previous_transaction_id uuid,
changed_conditions text[] not null default '{}'::text[],
material_change boolean not null,
evidence_graph_reference uuid,
replay_reference uuid,
trust_memory_reference uuid,
external_state text not null default 'NOT_REQUESTED'::text,
external_request_reference uuid,
external_acknowledgement_reference uuid,
external_outcome_reference uuid,
created_at timestamp with time zone not null default now(),
updated_at timestamp with time zone not null default now(),
operational_entity_id text,
accountable_owner_id text,
entity_type text,
entity_lifecycle_state text,
responsibility_lineage jsonb not null default '{}'::jsonb,
evidence_independence text not null default 'insufficient'::text,
decision_time_snapshot jsonb not null default '{}'::jsonb,
continuity_signals jsonb not null default '{}'::jsonb,
provider_neutral_evidence jsonb not null default '[]'::jsonb,
deployment_gate jsonb,
execution_continuity jsonb not null default '[]'::jsonb,
decision_outcome_review jsonb
);
create table public.evidence_graph_edges (
edge_id uuid not null default gen_random_uuid(),
enterprise_id uuid not null,
from_node_id uuid not null,
to_node_id uuid not null,
edge_type text not null,
evidence_id uuid,
created_at timestamp with time zone not null default now(),
correlation_id uuid
);
create table public.evidence_graph_nodes (
node_id uuid not null default gen_random_uuid(),
enterprise_id uuid not null,
node_type text not null,
external_id text not null,
domain_key text,
label text,
metadata jsonb not null default '{}'::jsonb,
created_at timestamp with time zone not null default now(),
correlation_id uuid
);
create table public.evidence_objects (
id uuid not null default gen_random_uuid(),
enterprise_id uuid not null,
envelope_id uuid,
provider_key text not null,
evidence_classification text not null,
storage_boundary text not null,
object_reference text,
object_encrypted boolean not null default false,
normalized_facts jsonb not null default '{}'::jsonb,
occurred_at timestamp with time zone not null,
retention_expires_at timestamp with time zone,
legal_hold boolean not null default false,
created_at timestamp with time zone not null default now(),
evidence_id uuid not null,
domain_key text not null,
subject_id text not null,
subject_type text not null,
evidence_type text not null,
source_type text not null,
source_key text not null,
result text not null,
assurance_level text not null,
cryptographically_verified boolean not null,
server_verified boolean not null,
received_at timestamp with time zone not null,
expires_at timestamp with time zone,
payload_hash text not null,
canonicalization text not null,
hash_algorithm text not null,
reason_codes text[] not null,
observed_at timestamp with time zone not null,
freshness_policy_seconds integer not null,
revoked_at timestamp with time zone,
superseded_by_evidence_id uuid
);
create table public.incident_chronology_events (
id uuid not null,
enterprise_id uuid not null,
incident_id uuid not null,
event_type text not null,
source text not null,
source_type text not null,
source_authority text not null,
occurred_at timestamp with time zone not null,
timestamp_confidence text not null,
ingested_at timestamp with time zone not null,
ordering_confidence text not null,
evidence_reference text,
integrity_state text not null,
classification text not null,
summary text not null,
containment_state text,
deadline_metadata jsonb,
correlation_id uuid not null,
supersedes_event_id uuid,
record_hash text not null,
created_at timestamp with time zone not null default now()
);
create table public.incident_regulatory_assessments (
id uuid not null,
enterprise_id uuid not null,
ai_system_id text not null,
agent_id text not null,
incident_category text not null,
jurisdiction text not null,
initial_state text not null,
canonical_case jsonb not null,
immutable_hash text not null,
created_by uuid not null,
correlation_id uuid not null,
created_at timestamp with time zone not null
);
create table public.incident_submission_packages (
id uuid not null,
enterprise_id uuid not null,
incident_id uuid not null,
version integer not null,
state text not null,
package_payload jsonb not null,
content_digest text not null,
package_digest text not null,
record_hash text not null,
export_schema_version text not null,
exported_at timestamp with time zone not null,
approved_by_decision_id uuid,
supersedes_package_id uuid,
correlation_id uuid not null,
created_at timestamp with time zone not null default now()
);
create table public.trust_memory_index (
memory_id uuid not null default gen_random_uuid(),
enterprise_id uuid not null,
subject_id text not null,
domain_key text not null,
memory_type text not null,
source_id text not null,
occurred_at timestamp with time zone not null,
summary jsonb not null default '{}'::jsonb,
created_at timestamp with time zone not null default now(),
correlation_id uuid
);
create table public.trust_workspaces (
id uuid not null default gen_random_uuid(),
name text,
slug text,
description text,
created_by uuid,
created_at timestamp with time zone default now()
);
alter table trust_workspaces add primary key(id);
alter table api_keys add primary key(id);
alter table api_keys add constraint api_keys_scope_v1_check check(scopes is not null);
alter table canonical_trust_transactions add unique(enterprise_id,transaction_id);
alter table incident_regulatory_assessments add unique(enterprise_id,id);
alter table incident_chronology_events add unique(enterprise_id,incident_id,id);
alter table evidence_graph_nodes add unique(enterprise_id,node_type,external_id);
create function user_can_access_trust_workspace(t uuid) returns boolean language sql stable as $$ select t::text=current_setting('test.tenant',true) $$;
create function prevent_serious_incident_history_mutation() returns trigger language plpgsql as $$ begin raise exception 'append-only'; end $$;
